page_id_valid.kernel_code:
pub fn page_id_valid(id: u32) -> bool {
    id >= CAP_A as u32 && id <= CAP_Z as u32
}

pages_valid.kernel_code:
pub fn pages_valid(pages: &[u8]) -> bool {
    let mut i: usize = 0;
    while i < pages.len() {
        if !page_id_valid(pages[i] as u32) {
            return false;
        }
        i += 1;
    }
    true
}

schedule_id_valid.kernel_code:
pub fn schedule_id_valid(id: u32) -> bool {
    id >= CAP_A as u32 && id <= CAP_E as u32
}

encode_message.kernel_code:
pub fn encode_message(msg: &[u8], out: &mut [u8]) -> Option<usize> {
    let mut i: usize = 0;
    let mut n: usize = 0;
    while i < msg.len() {
        let b = msg[i];
        if b == LT || b == GT {
            return None;
        }
        let code = if b == UTF8_C3 && i + 1 < msg.len() { umlaut_code(msg[i + 1]) } else { 0 };
        if code != 0 {
            if out.len() < 5 || n > out.len() - 5 {
                return None;
            }
            out[n] = LT;
            out[n + 1] = CAP_U;
            out[n + 2] = hex_upper(code >> 4);
            out[n + 3] = hex_upper(code & 15);
            out[n + 4] = GT;
            n += 5;
            i += 2;
        } else {
            if n >= out.len() {
                return None;
            }
            out[n] = b;
            n += 1;
            i += 1;
        }
    }
    Some(n)
}

ota_start.kernel_code:
pub fn ota_start(octet_stream: bool, content_length: usize, transfer_encoding: bool) -> OtaStart {
    if !octet_stream {
        OtaStart::WrongContentType
    } else if content_length == 0 {
        if transfer_encoding { OtaStart::Chunked } else { OtaStart::Empty }
    } else {
        OtaStart::Proceed
    }
}

OtaStart.kernel_code:
pub enum OtaStart {
    WrongContentType,
    Chunked,
    Empty,
    Proceed,
}

two_digits.kernel_code:
pub fn two_digits(v: u8) -> bool {
    v <= 99
}

waiting_time_valid.kernel_code:
pub fn waiting_time_valid(v: u8) -> bool {
    v <= WAITING_TIME_MAX
}

ota_complete.kernel_code:
pub fn ota_complete(bytes_written: usize, content_length: usize, remainder: usize) -> bool {
    remainder == 0 && bytes_written == content_length
}
